"""Starting-point graphs for the pedalboard: read-only templates shipped in tools/fx_lab/starters (generated by migrate_scenarios.py).

The editor copies one into a new graph; nothing here writes. A malformed file is skipped and reported through `notes` and the log, because one
bad file must not take the whole palette of starting points down."""
from __future__ import annotations

import json
import logging

from .config import Config

log = logging.getLogger(__name__)
STARTERS_DIR = ("tools", "fx_lab", "starters")
CATEGORY_ORDER = ["Clean", "Machine", "Vox", "Helmet", "Ethereal", "Monstrous", "Space", "Rogue Trader", "Test"]
FIELDS = ("name", "description", "category", "graph")


def list_starters(cfg: Config, notes: list[str] | None = None) -> list[dict]:
    """[{slug, name, description, category, graph}] sorted by category order (unknown categories last) then name.

    `notes`, when given, receives one line per skipped file saying why."""
    folder = cfg.root.joinpath(*STARTERS_DIR)
    found: list[dict] = []
    for p in sorted(folder.glob("*.json")) if folder.is_dir() else []:
        try:
            data = json.loads(p.read_text(encoding="utf-8"))
            if not isinstance(data, dict) or not isinstance(data.get("graph"), dict):
                raise ValueError("expected an object with a graph object")
            if not all(isinstance(data.get(k), str) for k in ("name", "category")):
                raise ValueError("name and category must be text")
        except (OSError, ValueError) as e:                       # json.JSONDecodeError and UnicodeDecodeError are ValueErrors
            note = f"skipped starter {p.name}: {e}"
            log.warning(note)
            if notes is not None:
                notes.append(note)
            continue
        found.append({"slug": p.stem, "name": data["name"], "description": str(data.get("description", "")),
                      "category": data["category"], "graph": data["graph"]})
    rank = {c: i for i, c in enumerate(CATEGORY_ORDER)}
    return sorted(found, key=lambda s: (rank.get(s["category"], len(rank)), s["name"].lower(), s["slug"]))
